#include <iostream>
#include <sstream>
#include <string>
int main() {
    std::istringstream csv{"item,quantity\npen,3\nbook,2\n"};
    std::string line; std::getline(csv, line); // header
    int rows = 0, total = 0;
    while (std::getline(csv, line)) {
        std::istringstream row(line); std::string item, count_text;
        if (!std::getline(row, item, ',') || !std::getline(row, count_text)) continue;
        try { total += std::stoi(count_text); ++rows; } catch (const std::exception&) { /* reject malformed row */ }
    }
    std::cout << "rows=" << rows << ", total=" << total << '\n';
}
